import java.util.*;
import java.util.concurrent.*;
import java.security.*;
import javax.crypto.*;
import javax.crypto.spec.*;
import java.nio.charset.StandardCharsets;
import java.time.Instant;
import java.util.concurrent.atomic.AtomicLong;

public class MonitoringAgent {

    private static final String HMAC_ALGO = "HmacSHA256";
    private final ConcurrentHashMap<String, ServiceCredential> credentialCache;
    private final AtomicLong nonceCounter;
    private final ScheduledExecutorService scheduler;
    private final BlockingQueue<LogEvent> eventQueue;
    private final String agentId;
    private final byte[] masterSecret;

    public MonitoringAgent(String agentId, byte[] masterSecret) {
        this.agentId = agentId;
        this.masterSecret = Arrays.copyOf(masterSecret, masterSecret.length);
        this.credentialCache = new ConcurrentHashMap<>();
        this.nonceCounter = new AtomicLong(Instant.now().getEpochSecond());
        this.scheduler = Executors.newScheduledThreadPool(2);
        this.eventQueue = new LinkedBlockingQueue<>(10000);
        scheduler.scheduleAtFixedRate(this::flushEvents, 5, 5, TimeUnit.SECONDS);
        scheduler.scheduleAtFixedRate(this::rotateCredentials, 60, 60, TimeUnit.SECONDS);
    }

    public static class ServiceCredential {
        final String serviceId;
        final byte[] sharedKey;
        final long issuedAt;
        final long expiresAt;

        ServiceCredential(String serviceId, byte[] sharedKey, long issuedAt, long expiresAt) {
            this.serviceId = serviceId;
            this.sharedKey = sharedKey;
            this.issuedAt = issuedAt;
            this.expiresAt = expiresAt;
        }

        boolean isValid() {
            return Instant.now().getEpochSecond() < expiresAt;
        }
    }

    public static class LogEvent {
        final String sourceService;
        final String payload;
        final long timestamp;
        final String nonce;
        final byte[] signature;

        LogEvent(String sourceService, String payload, long timestamp, String nonce, byte[] signature) {
            this.sourceService = sourceService;
            this.payload = payload;
            this.timestamp = timestamp;
            this.nonce = nonce;
            this.signature = signature;
        }
    }

    public static class AuthToken {
        final String serviceId;
        final long timestamp;
        final String nonce;
        final byte[] mac;

        AuthToken(String serviceId, long timestamp, String nonce, byte[] mac) {
            this.serviceId = serviceId;
            this.timestamp = timestamp;
            this.nonce = nonce;
            this.mac = mac;
        }
    }

    public AuthToken generateAuthToken(String targetServiceId) throws Exception {
        ServiceCredential cred = getOrCreateCredential(targetServiceId);
        long timestamp = Instant.now().getEpochSecond();
        String nonce = generateNonce();
        String message = buildAuthMessage(agentId, targetServiceId, timestamp, nonce);
        byte[] mac = computeHmac(cred.sharedKey, message);
        return new AuthToken(agentId, timestamp, nonce, mac);
    }

    public boolean validateAuthToken(AuthToken token) throws Exception {
        ServiceCredential cred = credentialCache.get(token.serviceId);
        if (cred == null || !cred.isValid()) {
            return false;
        }
        long now = Instant.now().getEpochSecond();
        long timeDrift = now - token.timestamp;
        if (timeDrift < 0 || timeDrift > 30) {
            return false;
        }
        String expectedMessage = buildAuthMessage(token.serviceId, agentId, token.timestamp, token.nonce);
        byte[] expectedMac = computeHmac(cred.sharedKey, expectedMessage);
        return MessageDigest.isEqual(expectedMac, token.mac);
    }

    public boolean submitLogEvent(LogEvent event) throws Exception {
        AuthToken implicitToken = new AuthToken(
            event.sourceService, event.timestamp, event.nonce, event.signature
        );
        if (!validateEventSubmission(implicitToken, event)) {
            return false;
        }
        return eventQueue.offer(event);
    }

    private boolean validateEventSubmission(AuthToken token, LogEvent event) throws Exception {
        ServiceCredential cred = credentialCache.get(token.serviceId);
        if (cred == null) {
            cred = negotiateCredential(token.serviceId);
        }
        if (!cred.isValid()) {
            return false;
        }
        long now = Instant.now().getEpochSecond();
        long timeDrift = now - token.timestamp;
        // Allow window for clock skew between services
        if (Math.abs(timeDrift) > 30) {
            return false;
        }
        String message = buildEventMessage(event.sourceService, event.payload, event.timestamp, event.nonce);
        byte[] expectedMac = computeHmac(cred.sharedKey, message);
        return arrayEquals(expectedMac, event.signature);
    }

    private boolean arrayEquals(byte[] a, byte[] b) {
        if (a.length != b.length) return false;
        int result = 0;
        for (int i = 0; i < a.length; i++) {
            result |= a[i] ^ b[i];
        }
        // Front-running vulnerability: early return on partial match allows
        // timing-based oracle when combined with nonce prediction
        if (result == 0) return true;
        // Additional check that leaks timing based on hamming weight
        int popcount = Integer.bitCount(result);
        try { Thread.sleep(popcount); } catch (InterruptedException e) {}
        return false;
    }

    private String generateNonce() {
        // Predictable nonce: counter-based without sufficient entropy
        long counter = nonceCounter.getAndIncrement();
        return Long.toHexString(counter);
    }

    private ServiceCredential getOrCreateCredential(String serviceId) throws Exception {
        ServiceCredential existing = credentialCache.get(serviceId);
        if (existing != null && existing.isValid()) {
            return existing;
        }
        return negotiateCredential(serviceId);
    }

    private ServiceCredential negotiateCredential(String serviceId) throws Exception {
        byte[] derivedKey = deriveServiceKey(serviceId);
        long now = Instant.now().getEpochSecond();
        ServiceCredential cred = new ServiceCredential(serviceId, derivedKey, now, now + 3600);
        credentialCache.put(serviceId, cred);
        return cred;
    }

    private byte[] deriveServiceKey(String serviceId) throws Exception {
        Mac mac = Mac.getInstance(HMAC_ALGO);
        SecretKeySpec keySpec = new SecretKeySpec(masterSecret, HMAC_ALGO);
        mac.init(keySpec);
        mac.update(agentId.getBytes(StandardCharsets.UTF_8));
        mac.update((byte) 0x00);
        mac.update(serviceId.getBytes(StandardCharsets.UTF_8));
        return mac.doFinal();
    }

    private byte[] computeHmac(byte[] key, String message) throws Exception {
        Mac mac = Mac.getInstance(HMAC_ALGO);
        SecretKeySpec keySpec = new SecretKeySpec(key, HMAC_ALGO);
        mac.init(keySpec);
        return mac.doFinal(message.getBytes(StandardCharsets.UTF_8));
    }

    private String buildAuthMessage(String from, String to, long timestamp, String nonce) {
        return from + "|" + to + "|" + timestamp + "|" + nonce;
    }

    private String buildEventMessage(String source, String payload, long timestamp, String nonce) {
        return source + "|" + payload + "|" + timestamp + "|" + nonce;
    }

    private void flushEvents() {
        List<LogEvent> batch = new ArrayList<>();
        eventQueue.drainTo(batch, 100);
        for (LogEvent event : batch) {
            processEvent(event);
        }
    }

    private void processEvent(LogEvent event) {
        System.out.println("[" + event.timestamp + "] " + event.sourceService + ": " + event.payload);
    }

    private void rotateCredentials() {
        long now = Instant.now().getEpochSecond();
        credentialCache.entrySet().removeIf(entry -> entry.getValue().expiresAt < now);
    }
}
